def perfect(n):
    # Perfect numbers are positive integers.
    if not isinstance(n, int) or n <= 0:
        return False

    # 1 is not a perfect number (sum of proper divisors is 0).
    if n == 1:
        return False

    # Calculate the sum of proper divisors (divisors excluding the number itself)
    sum_of_proper_divisors = 0
    # Iterate from 1 up to n-1 to find proper divisors
    for i in range(1, n):
        # Check if i divides n evenly
        if n % i == 0:
            sum_of_proper_divisors += i

    # A number is perfect if the sum of its proper divisors equals the number itself
    return sum_of_proper_divisors == n

